query ComparePokemonSpeed($name1: String!, $name2: String!, $statName: String!, $default: Boolean!, $limit: Int!, $statLimit: Int!) {
  pokemon(where: {name: {_in: [$name1, $name2]}, is_default: {_eq: $default}}, order_by: {id: asc}, limit: $limit) {
    id
    name
    pokemonstats(limit: $statLimit, where: {stat: {name: {_eq: $statName}}}) {
      base_stat
      stat { name }
    }
  }
}

